// Set timestamp variables
const now = new Date();
const sixHoursFromNow = new Date(now.getTime() + (6 * 60 * 60 * 1000));
const twentyFourHoursAgo = new Date(now.getTime() - (24 * 60 * 60 * 1000));
const sevenDaysAgo = new Date(now.getTime() - (7 * 24 * 60 * 60 * 1000));

return [{
  json: {
    now: now.toISOString(),
    nowDate: now.toISOString().split('T')[0],
    sixHoursFromNow: sixHoursFromNow.toISOString(),
    twentyFourHoursAgo: twentyFourHoursAgo.toISOString(),
    sevenDaysAgo: sevenDaysAgo.toISOString()
  }
}];

// Categorize expenses by urgency
const items = $input.all();
const now = new Date();
const sixHours = 6 * 60 * 60 * 1000;
const twentyFourHours = 24 * 60 * 60 * 1000;
const sevenDays = 7 * 24 * 60 * 60 * 1000;

const categorized = {
  overdue: [],
  dueSoon: [],
  upcoming: [],
  critical: [] // High value + overdue > 7 days
};

for (const item of items) {
  const expense = item.json;
  const deadlineStr = expense.properties?.['Validation Deadline']?.date?.start;
  const amount = expense.properties?.Amount?.number || 0;
  const merchant = expense.properties?.Expense?.title?.[0]?.plain_text || 'Unknown';
  const expenseUrl = expense.url || '';

  if (!deadlineStr) continue;

  const deadline = new Date(deadlineStr);
  const timeUntil = deadline - now;

  const expenseData = {
    id: expense.id,
    merchant,
    amount,
    deadline: deadline.toISOString(),
    url: expenseUrl
  };

  if (timeUntil < 0) {
    // Overdue
    const hoursOverdue = Math.abs(timeUntil) / (60 * 60 * 1000);
    const daysOverdue = Math.floor(hoursOverdue / 24);
    expenseData.hoursOverdue = Math.round(hoursOverdue);
    expenseData.daysOverdue = daysOverdue;
    categorized.overdue.push(expenseData);

    // Check if critical (>$500 AND >7 days overdue)
    if (amount > 500 && hoursOverdue > 7 * 24) {
      categorized.critical.push(expenseData);
    }
  } else if (timeUntil <= sixHours) {
    // Due soon (within 6 hours)
    const hoursRemaining = Math.round(timeUntil / (60 * 60 * 1000));
    expenseData.hoursRemaining = hoursRemaining;
    categorized.dueSoon.push(expenseData);
  } else if (timeUntil <= twentyFourHours) {
    // Upcoming (6-24 hours)
    const hoursRemaining = Math.round(timeUntil / (60 * 60 * 1000));
    expenseData.hoursRemaining = hoursRemaining;
    categorized.upcoming.push(expenseData);
  }
}

// Calculate totals
const overdueTotal = categorized.overdue.reduce((sum, e) => sum + e.amount, 0);
const dueSoonTotal = categorized.dueSoon.reduce((sum, e) => sum + e.amount, 0);
const upcomingTotal = categorized.upcoming.reduce((sum, e) => sum + e.amount, 0);
const criticalTotal = categorized.critical.reduce((sum, e) => sum + e.amount, 0);

const needsNotification = categorized.overdue.length > 0 || categorized.dueSoon.length > 0;
const hasCritical = categorized.critical.length > 0;

return [{
  json: {
    categorized,
    counts: {
      overdue: categorized.overdue.length,
      dueSoon: categorized.dueSoon.length,
      upcoming: categorized.upcoming.length,
      critical: categorized.critical.length
    },
    totals: {
      overdue: overdueTotal,
      dueSoon: dueSoonTotal,
      upcoming: upcomingTotal,
      critical: criticalTotal
    },
    needsNotification,
    hasCritical
  }
}];

// Format Slack message
const data = $input.first().json;
const { categorized, counts, totals } = data;

const formatExpense = (exp, isOverdue = false) => {
  const timeStr = isOverdue 
    ? (exp.daysOverdue > 0 ? `${exp.daysOverdue}d ${exp.hoursOverdue % 24}h overdue` : `${exp.hoursOverdue}h overdue`)
    : `${exp.hoursRemaining}h remaining`;
  return `• $${exp.amount.toFixed(2)} ${exp.merchant} - <${exp.url}|Add Receipt> (${timeStr})`;
};

let message = ':rotating_light: *EXPENSE RECEIPTS NEEDED*\n\n';

if (counts.overdue > 0) {
  message += `*OVERDUE (${counts.overdue}) - $${totals.overdue.toFixed(2)}:*\n`;
  categorized.overdue.forEach(exp => {
    message += `${formatExpense(exp, true)}\n`;
  });
  message += '\n';
}

if (counts.dueSoon > 0) {
  message += `*DUE SOON - Next 6 Hours (${counts.dueSoon}) - $${totals.dueSoon.toFixed(2)}:*\n`;
  categorized.dueSoon.forEach(exp => {
    message += `${formatExpense(exp)}\n`;
  });
  message += '\n';
}

// Only show upcoming if list is short
if (counts.upcoming > 0 && counts.upcoming <= 5) {
  message += `*UPCOMING - Next 24 Hours (${counts.upcoming}) - $${totals.upcoming.toFixed(2)}:*\n`;
  categorized.upcoming.forEach(exp => {
    message += `${formatExpense(exp)}\n`;
  });
  message += '\n';
}

message += `\n:clipboard: <https://notion.so|View All Pending Receipts>`;

return [{
  json: {
    ...data,
    slackMessage: message
  }
}];

// Format critical items for email
const data = $input.first().json;
const critical = data.categorized.critical;

let itemsList = '';
critical.forEach(exp => {
  itemsList += `<tr>
    <td style="padding: 8px; border-bottom: 1px solid #eee;">${exp.merchant}</td>
    <td style="padding: 8px; border-bottom: 1px solid #eee;">$${exp.amount.toFixed(2)}</td>
    <td style="padding: 8px; border-bottom: 1px solid #eee;">${exp.daysOverdue} days</td>
    <td style="padding: 8px; border-bottom: 1px solid #eee;"><a href="${exp.url}">Add Receipt</a></td>
  </tr>`;
});

const emailHtml = `
<html>
<body style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
  <div style="background: #fee2e2; padding: 20px; border-radius: 8px; margin-bottom: 20px;">
    <h1 style="color: #dc2626; margin-top: 0;">:warning: URGENT: High-Value Receipts Overdue</h1>
    <p>The following high-value expenses are missing receipts and are significantly overdue:</p>
  </div>

  <table style="width: 100%; border-collapse: collapse; margin-bottom: 20px;">
    <thead>
      <tr style="background: #f3f4f6;">
        <th style="padding: 12px; text-align: left;">Merchant</th>
        <th style="padding: 12px; text-align: left;">Amount</th>
        <th style="padding: 12px; text-align: left;">Days Overdue</th>
        <th style="padding: 12px; text-align: left;">Action</th>
      </tr>
    </thead>
    <tbody>
      ${itemsList}
    </tbody>
  </table>

  <div style="background: #fef3c7; padding: 15px; border-radius: 8px;">
    <p style="margin: 0;"><strong>Total at risk:</strong> $${data.totals.critical.toFixed(2)}</p>
    <p style="margin: 10px 0 0 0;">These items must be addressed immediately for tax compliance. Expenses without receipts may not be deductible.</p>
  </div>

  <p style="margin-top: 20px;">
    <a href="https://notion.so" style="background: #dc2626; color: white; padding: 12px 24px; text-decoration: none; border-radius: 6px; display: inline-block;">View and Add Receipts</a>
  </p>
</body>
</html>
`;

return [{
  json: {
    ...data,
    emailHtml,
    emailSubject: `URGENT: ${data.counts.critical} High-Value Receipts Overdue ($${data.totals.critical.toFixed(2)})`
  }
}];

// Flag critical items in Notion
const data = $input.first().json;
const critical = data.categorized.critical;

// Return items to update
return critical.map(exp => ({
  json: {
    expenseId: exp.id,
    note: `:rotating_light: CRITICAL: High-value receipt overdue >${exp.daysOverdue} days. Amount: $${exp.amount.toFixed(2)}`
  }
}));

// No notification needed - log for debugging
return [{
  json: {
    status: 'skipped',
    reason: 'No overdue or due soon receipts',
    timestamp: new Date().toISOString()
  }
}];
